@page "/shipments"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]

@inject IShipmentService ShipmentService

<PageTitle>Shipments - Dispatcher View</PageTitle>

<div class="container mt-4">
    <div class="d-flex justify-content-between align-items-center mb-4">
        <h2>📦 Shipments</h2>
        <button class="btn btn-success" @onclick="ShowCreateForm">
            ➕ New Shipment
        </button>
    </div>

    @if (showCreateForm)
    {
        <div class="card mb-4">
            <div class="card-header">Create New Shipment</div>
            <div class="card-body">
                <div class="row g-3">
                    <div class="col-md-4">
                        <label class="form-label">Origin</label>
                        <input class="form-control" @bind="newShipment.Origin" placeholder="e.g. New York, NY" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Destination</label>
                        <input class="form-control" @bind="newShipment.Destination" placeholder="e.g. London, UK" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Customer Email</label>
                        <input class="form-control" type="email" @bind="newShipment.CustomerEmail" placeholder="customer@example.com" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Description</label>
                        <input class="form-control" @bind="newShipment.Description" placeholder="Package contents" />
                    </div>
                    <div class="col-md-3">
                        <label class="form-label">Estimated Delivery</label>
                        <input class="form-control" type="date" @bind="newShipment.EstimatedDelivery" />
                    </div>
                    <div class="col-md-3 d-flex align-items-end gap-2">
                        <button class="btn btn-primary" @onclick="CreateShipment" disabled="@isCreating">
                            @(isCreating ? "Creating..." : "Create")
                        </button>
                        <button class="btn btn-secondary" @onclick="CancelCreate">Cancel</button>
                    </div>
                </div>
                @if (!string.IsNullOrEmpty(createError))
                {
                    <div class="alert alert-danger mt-3">@createError</div>
                }
            </div>
        </div>
    }

    <div class="row mb-3">
        <div class="col-md-4">
            <input class="form-control" placeholder="Filter by destination..." @bind="filterText" @bind:event="oninput" />
        </div>
        <div class="col-md-3">
            <select class="form-select" @bind="filterStatus">
                <option value="">All Statuses</option>
                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@status">@status</option>
                }
            </select>
        </div>
    </div>

    @if (shipments is null)
    {
        <p class="text-muted">Loading shipments...</p>
    }
    else if (!FilteredShipments.Any())
    {
        <div class="alert alert-info">No shipments found.</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                        <th>Last Updated</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in FilteredShipments)
                    {
                        <tr>
                            <td><code>@s.TrackingNumber</code></td>
                            <td>@s.Origin</td>
                            <td>@s.Destination</td>
                            <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                            <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                            <td>@s.LastUpdated.ToString("MMM dd, yyyy HH:mm")</td>
                            <td>
                                <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                        value="@s.Status"
                                        @onchange="e => UpdateStatus(s.Id, e)">
                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@status">@status</option>
                                    }
                                </select>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    private List<Shipment>? shipments;
    private Shipment newShipment = new() { EstimatedDelivery = DateTime.Today.AddDays(7) };
    private bool showCreateForm;
    private bool isCreating;
    private string? createError;
    private string filterText = "";
    private string filterStatus = "";

    private IEnumerable<Shipment> FilteredShipments =>
        (shipments ?? []).Where(s =>
            (string.IsNullOrWhiteSpace(filterText) ||
             s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
             s.Origin.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
             s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase)) &&
            (string.IsNullOrWhiteSpace(filterStatus) ||
             s.Status.ToString() == filterStatus));

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ShowCreateForm() => showCreateForm = true;
    private void CancelCreate()
    {
        showCreateForm = false;
        createError = null;
        newShipment = new() { EstimatedDelivery = DateTime.Today.AddDays(7) };
    }

    private async Task CreateShipment()
    {
        createError = null;
        if (string.IsNullOrWhiteSpace(newShipment.Origin) || string.IsNullOrWhiteSpace(newShipment.Destination))
        {
            createError = "Origin and Destination are required.";
            return;
        }

        isCreating = true;
        try
        {
            var created = await ShipmentService.CreateShipmentAsync(newShipment);
            shipments?.Insert(0, created);
            CancelCreate();
        }
        catch (Exception ex)
        {
            createError = $"Failed to create shipment: {ex.Message}";
        }
        finally
        {
            isCreating = false;
        }
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
            var index = shipments?.FindIndex(s => s.Id == id) ?? -1;
            if (index >= 0 && shipments is not null)
                shipments[index] = updated;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Cancelled => "bg-dark",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services

@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<div class="container mt-4">
    <h2 class="mb-4">🔍 Track Your Shipment</h2>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input class="form-control form-control-lg" placeholder="Enter tracking number (e.g. SHP-20260629-A1B2C3D4)"
                       @bind="trackingNumber" @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary btn-lg" @onclick="TrackShipment" disabled="@isSearching">
                    @(isSearching ? "Searching..." : "Track")
                </button>
            </div>
        </div>
    </div>

    @if (hasSearched && shipment is null && !isSearching)
    {
        <div class="alert alert-warning">
            <strong>Shipment not found.</strong> Please check your tracking number and try again.
        </div>
    }

    @if (shipment is not null)
    {
        <div class="card shadow-sm">
            <div class="card-header bg-dark text-white d-flex justify-content-between align-items-center">
                <span>Tracking: <strong>@shipment.TrackingNumber</strong></span>
                <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
            </div>
            <div class="card-body">
                <div class="row g-3">
                    <div class="col-md-6">
                        <h6 class="text-muted">Origin</h6>
                        <p class="fs-5">@shipment.Origin</p>
                    </div>
                    <div class="col-md-6">
                        <h6 class="text-muted">Destination</h6>
                        <p class="fs-5">@shipment.Destination</p>
                    </div>
                    <div class="col-md-6">
                        <h6 class="text-muted">Estimated Delivery</h6>
                        <p class="fs-5">@(shipment.EstimatedDelivery?.ToString("dddd, MMMM dd, yyyy") ?? "Not yet determined")</p>
                    </div>
                    <div class="col-md-6">
                        <h6 class="text-muted">Last Updated</h6>
                        <p class="fs-5">@shipment.LastUpdated.ToString("MMMM dd, yyyy HH:mm") UTC</p>
                    </div>
                    @if (!string.IsNullOrWhiteSpace(shipment.Description))
                    {
                        <div class="col-12">
                            <h6 class="text-muted">Description</h6>
                            <p>@shipment.Description</p>
                        </div>
                    }
                </div>

                <hr />
                <h6 class="text-muted mb-3">Shipment Progress</h6>
                <div class="d-flex justify-content-between">
                    @foreach (var step in progressSteps)
                    {
                        var isActive = (int)shipment.Status >= step.Order;
                        var isCurrent = shipment.Status.ToString() == step.Name;
                        <div class="text-center flex-fill">
                            <div class="rounded-circle mx-auto d-flex align-items-center justify-content-center @(isActive ? "bg-success text-white" : "bg-light text-muted border")"
                                 style="width: 40px; height: 40px; @(isCurrent ? "box-shadow: 0 0 0 3px rgba(25,135,84,.5);" : "")">
                                @step.Icon
                            </div>
                            <small class="@(isActive ? "fw-bold" : "text-muted")">@step.Name</small>
                        </div>
                    }
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string trackingNumber = "";
    private Shipment? shipment;
    private bool isSearching;
    private bool hasSearched;

    private record ProgressStep(string Name, string Icon, int Order);

    private readonly ProgressStep[] progressSteps =
    [
        new("Pending", "📋", 0),
        new("PickedUp", "🚚", 1),
        new("InTransit", "✈️", 2),
        new("OutForDelivery", "🏠", 3),
        new("Delivered", "✅", 4)
    ];

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isSearching = true;
        hasSearched = true;
        shipment = null;

        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
        }
        finally
        {
            isSearching = false;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Cancelled => "bg-dark",
        _ => "bg-secondary"
    };
}

